        '你热情且行动导向，善于发现即时机会，并以灵活与热忱作出决策。',
    'Expressive and imaginative, you connect ideas quickly and gain energy from discovering new directions with others.':
        '你善于表达且富想象力，能迅速连接想法，并从共同探索新方向中获得能量。',
    'Quick and exploratory, you enjoy testing alternatives, questioning assumptions, and adapting promising ideas.':
        '你思维敏捷且喜欢探索，乐于测试替代方案、质疑假设并调整有潜力的想法。',
    'Direct and practical, you turn observable facts into organized action and prefer clear ownership and standards.':
        '你直接务实，能把可观察事实转化为有组织的行动，并偏好明确责任与标准。',
    'Sociable and dependable, you organize practical details while considering how decisions affect the group.':
        '你合群可靠，会组织实际细节，同时考虑决策对群体的影响。',
    'Expressive and future-aware, you organize people and ideas around shared development and meaningful goals.':
        '你善于表达并关注未来，会围绕共同成长与有意义目标组织人员和想法。',
    'Decisive and future-focused, you organize complex work around measurable goals, logic, and efficient execution.':
        '你果断且关注未来，会围绕可衡量目标、逻辑与高效执行组织复杂工作。',

    // Guidance actions and cautions.
    'Use a fixed risk ceiling': '使用固定风险上限',
    'Set a daily loss limit': '设置每日亏损上限',
    'Require an entry checklist': '强制使用入场检查清单',
    'Predefine the exit decision': '预先定义离场决策',
    'Use a loss cooldown': '亏损后执行冷静期',
    'Limit trade frequency': '限制交易频率',
    'Interrupt FOMO': '打断错失恐惧',
    'Review process on a schedule': '按计划复盘流程',
    'Suggestion: risk no more than {risk}% per trade and never increase size to recover a loss.':
        '建议：每笔交易风险不超过 {risk}%，且绝不通过加仓来挽回亏损。',
    'Suggestion: stop new entries after {loss}% daily loss or two consecutive losses.':
        '建议：当日亏损达到 {loss}% 或连续两笔亏损后，停止新的入场。',
    'Suggestion: use {count} trades per day as a ceiling, not a target.':
        '建议：将每日 {count} 笔交易作为上限，而不是目标。',
    'Confirm structure, setup, entry, stop loss, target, risk, session, and psychology readiness before entry.':
        '入场前确认结构、形态、入场位、止损、目标、风险、交易时段及心理准备度。',
    'Record invalidation, stop loss, target, and the conditions for an early exit before activating the trade.':
        '激活交易前，记录失效条件、止损、目标以及提前离场条件。',
    'Pause for at least 30 minutes after a loss and complete a psychology check before another entry.':
        '亏损后暂停至少 30 分钟，并在再次入场前完成心理状态检查。',
    'This percentage is educational guidance, not a guaranteed safe level.':
        '此百分比仅为教育性建议，并非保证安全的水平。',
    'Use the stricter limit when a broker or approved Trading Plan requires one.':
        '若经纪商或获批准的交易计划有更严格限制，请采用更严格者。',
    'Checklist completion cannot guarantee a profitable trade.':
        '完成检查清单不能保证交易盈利。',
    'Market gaps and slippage can still exceed a planned exit.':
        '跳空与滑点仍可能超出计划离场价。',
    'A cooldown is a safeguard, not a signal to trade again when time expires.':
        '冷静期是保护措施，不代表时间结束后就应再次交易。',
    'Taking no trade is valid when no setup meets every rule.':
        '没有形态符合全部规则时，不交易是有效选择。',
    'If the planned entry is gone, wait for a new confirmed setup instead of chasing price.':
        '若计划入场位已错过，请等待新的确认形态，而不是追价。',
    'Missing an opportunity is preferable to abandoning the risk plan.':
        '错过机会也好过放弃风险计划。',
    'Review execution after each trade, journal patterns weekly, and repeat a psychology check before each session.':
        '每笔交易后复盘执行，每周检查日志模式，并在每个交易时段前进行心理检查。',
    'Do not replace a strategy because of a very small sample.':
        '不要因样本过少而更换策略。',
    'Under stress, activity and new opportunities may increase; a cooldown protects against impulsive frequency.':
        '压力下，活动与新机会可能增多；冷静期可防止冲动性频繁交易。',
    'Under stress, you may narrow your focus and hold tightly to the plan; pause to test whether assumptions changed.':
        '压力下，你可能缩小关注范围并固守计划；请暂停并检验假设是否已改变。',
    'Under stress, losses or conflict may feel personally significant; name the emotion before making another risk decision.':
        '压力下，亏损或冲突可能变得格外个人化；再次作出风险决策前，请先识别情绪。',
    'Under stress, analysis may become overly detached or repetitive; use a time limit and an objective stop condition.':
        '压力下，分析可能过度抽离或反复；请设置时间限制和客观停止条件。',
    'A strong preference can magnify both strengths and blind spots. Consider a suggested maximum risk of 0.5% per trade until journal evidence supports a change.':
        '强烈偏好会同时放大优势与盲点。在交易日志证据支持调整前，可考虑将每笔建议最高风险设为 0.5%。',
    'Balanced preferences may shift with context. Consider a suggested maximum risk of 1% per trade and evaluate consistency before changing it.':
        '平衡偏好可能随情境变化。可考虑将每笔建议最高风险设为 1%，并在调整前评估一致性。',
