  static AppLocalizations of(BuildContext context) {
    return Localizations.of<AppLocalizations>(context, AppLocalizations)!;
  }

  bool get isChinese => locale.languageCode == 'zh';

  String roleName(int roleId) =>
      AppRoles.localizedName(roleId, locale.languageCode);

  String roleDisplayName(String role) =>
      getRoleDisplayName(role, locale.languageCode);

  String text(String english, [Map<String, Object?> values = const {}]) {
    var translated = isChinese
        ? (_zhAdvancedAnalyticsOverrides[english] ??
              _zhAveragePriceOverrides[english] ??
              _zhPerformanceOverrides[english] ??
              _zhSignalLifecycleOverrides[english] ??
              _zhFinancialPlatformOverrides[english] ??
              _zhUserManagementOverrides[english] ??
              _zhCourseworkOverrides[english] ??
              _zhAnalyticsOverrides[english] ??
              _zhMt5ImportOverrides[english] ??
              _zhV6Overrides[english] ??
              _zhV5Overrides[english] ??
              _zhV4Overrides[english] ??
              _zhRecommendationOverrides[english] ??
              _zhTaskOverrides[english] ??
              _zhOverrides[english] ??
              _zh[english] ??
              accountSequenceZh[english] ??
              accountHealthZh[english] ??
              multiAccountPropFirmZh[english] ??
              _dynamicZhV5Text(english) ??
              _dynamicZhRecommendationText(english) ??
              _dynamicZhTradingReportText(english) ??
              english)
        : english;
    for (final entry in values.entries) {
      translated = translated.replaceAll('{${entry.key}}', '${entry.value}');
    }
    return translated;
  }

  static String? _dynamicZhV5Text(String english) {
    if (english.startsWith('Your selected risk preference is ')) {
      final value = english
          .substring('Your selected risk preference is '.length)
          .split('. A fixed limit')
          .first
          .replaceAll('not yet defined', '尚未定义');
      return '您选择的风险偏好为 $value。固定上限可减少受情绪影响的仓位调整。';
    }
    if (english.startsWith('Start with ')) {
      final value = english
          .substring('Start with '.length)
          .split(' maximum risk')
          .first;
      return '建议先以每笔交易最高 $value 风险作为草稿，并只在非交易时段复核。';
    }
    if (english.startsWith('Use ') &&
        english.contains(' trades per day as a draft ceiling')) {
      final value = english
          .substring('Use '.length)
          .split(' trades per day')
          .first;
      return '将每日 $value 笔交易作为草稿上限，并为每次进场完成一份设置清单。';
    }
    if (english.contains('may fit your current answers when entries')) {
      return '当进场与失效条件都有客观定义时，这类规则明确的风格可能适合您当前的答案。';
    }
    if (english.startsWith('Review ') &&
        english.contains('copy only the rules you understand')) {
      return '查看建议的相关策略，并只把您真正理解的规则复制到策略草稿。';
    }
    return null;
  }

