  static String? _dynamicZhRecommendationText(String english) {
    const allowedPrefix = 'Allowed strategies: ';
    const allowedSuffix = '. Choose only one active strategy per trade.';
    if (english.startsWith(allowedPrefix) && english.endsWith(allowedSuffix)) {
      final value = english.substring(
        allowedPrefix.length,
        english.length - allowedSuffix.length,
      );
      return '允许策略：${_translateInlineList(value)}。每笔交易只选择一个有效策略。';
    }

    const issuePrefix = 'Current psychology issue checked: ';
    if (english.startsWith(issuePrefix) && english.endsWith('.')) {
      final value = english.substring(issuePrefix.length, english.length - 1);
      return '已检查当前心理问题：${_translateInlineList(value)}。';
    }

    const reviewPrefix = 'Review these selected issues weekly: ';
    if (english.startsWith(reviewPrefix) && english.endsWith('.')) {
      final value = english.substring(reviewPrefix.length, english.length - 1);
      return '每周复盘这些已选问题：${_translateInlineList(value)}。';
    }

    const sessionsPrefix = 'Trade sessions: ';
    if (english.startsWith(sessionsPrefix) && english.endsWith('.')) {
      final value = english.substring(
        sessionsPrefix.length,
        english.length - 1,
      );
      return '交易时段：${_translateInlineList(value)}。';
    }

    const primaryPrefix = 'Primary technical method: ';
    if (english.startsWith(primaryPrefix) && english.endsWith('.')) {
      final value = english.substring(primaryPrefix.length, english.length - 1);
      return '主要技术方法：${_translateInlineList(value)}。';
    }

    const supportingPrefix = 'Supporting methods: ';
    if (english.startsWith(supportingPrefix)) {
      final value = english.substring(supportingPrefix.length);
      return '辅助方法：${_translateInlineList(value)}';
    }

    final confirm = RegExp(
      r'^Confirm market direction on (.+), then execute only after the setup appears on (.+)\.$',
    ).firstMatch(english);
    if (confirm != null) {
      return '先在 ${confirm.group(1)} 确认市场方向，然后只在 ${confirm.group(2)} 出现形态后执行。';
    }

    final entry = RegExp(
      r'^Wait for (.+), then enter with (.+)\.$',
    ).firstMatch(english);
    if (entry != null) {
      return '等待${_translateInlineTerm(entry.group(1)!)}，然后使用${_translateInlineTerm(entry.group(2)!)}入场。';
    }

    final inlineList = _translateInlineListIfKnown(english);
    if (inlineList != null) return inlineList;

    final labeled = RegExp(r'^([^:：]{1,60}):\s*(.+)$').firstMatch(english);
    if (labeled != null) {
      final label = labeled.group(1)!.trim();
      final value = labeled.group(2)!.trim();
      final translatedLabel = _translateInlineTerm(label);
      final translatedValue = _translateInlineList(value);
      if (translatedLabel != label || translatedValue != value) {
        return '$translatedLabel：$translatedValue';
      }
    }

    return null;
  }

  static String _translateInlineList(String value) {
    return value
        .split(',')
        .map((part) => _translateInlineTerm(part.trim()))
        .where((part) => part.isNotEmpty)
        .join('、');
  }

  static String _translateInlineTerm(String value) {
    return _zhRecommendationOverrides[value] ??
        _zhTaskOverrides[value] ??
        _zhOverrides[value] ??
        _zh[value] ??
        value;
  }

  static String? _translateInlineListIfKnown(String value) {
    if (!value.contains(',')) return null;
    final parts = value
        .split(',')
        .map((part) => part.trim())
        .where((part) => part.isNotEmpty)
        .toList();
    if (parts.length < 2) return null;
    final translated = <String>[];
    for (final part in parts) {
      final item = _translateInlineTerm(part);
      if (item == part) return null;
      translated.add(item);
    }
    return translated.join('、');
  }

