    'Focus on consistency first, not profit.': '优先关注一致性，而不是盈利。',
    'Missing a trade is better than entering late.': '错过交易好过迟到入场。',
    'Do not trade to recover losses.': '不要为了追回亏损而交易。',
    'Use smaller risk and wait for clear setups.': '使用更小风险，并等待清晰形态。',
    'After a loss, pause before looking for another setup.': '亏损后先暂停，再寻找下一个形态。',
    'Take a 15-30 minute cooldown after loss.': '亏损后冷静 15-30 分钟。',
    'Stop immediately when all-in or gambling urges appear.':
        '出现孤注一掷或赌博冲动时立即停止。',
    'Never increase lot size after a loss.': '亏损后绝不加大手数。',
    'Wait for retest or the next valid setup.': '等待回踩或下一个有效形态。',
    'Take a cooldown after missing a trade.': '错过交易后先冷静。',
    'Do not chase missed moves. Wait for the next planned setup.':
        '不要追错过的行情。等待下一个计划内形态。',
    'No lot increase after loss.': '亏损后不得加大手数。',
    'After a loss, take the next trade only if it fully qualifies.':
        '亏损后，只有下一笔交易完全符合条件才可执行。',
    'Breaking one rule ends the session.': '破坏一条规则即结束本交易时段。',
    'Checklist must be completed before every trade.': '每笔交易前必须完成检查清单。',
    'If discipline is weak, reduce the session to one planned trade decision.':
        '如果纪律较弱，把本时段减少到一个计划内交易决策。',
    'Do not trade when more than one selected psychology issue is active at the same time.':
        '当多个已选心理问题同时出现时，不交易。',
    'Record screenshot, result, emotion, and rule compliance.':
        '记录截图、结果、情绪和规则执行情况。',
    'Mark whether the selected strategy was followed.': '标记是否遵守了所选策略。',
    'Write one improvement note before the next trade.': '下一笔交易前先写一条改进备注。',
    'Review risk control, missed rules, best setups, and one improvement focus each week.':
        '每周复盘风险控制、错过的规则、最佳形态和一个改进重点。',
    'Build a 20-trade sample before increasing risk.': '提高风险前，先建立 20 笔交易样本。',
    'Track every missed trade and whether chasing would break the plan.':
        '记录每个错过的交易，并判断追单是否会破坏计划。',
    'Review losing trades only after cooldown.': '只在冷静期后复盘亏损交易。',
    'Use the journal to identify the most repeated mistake.':
        '使用交易日记找出最常重复的错误。',
    'Stop trading when daily risk limit or max losing trades is reached.':
        '达到每日风险限制或最大亏损交易数时停止交易。',
    'Daily loss limit is a platform-level stop; no manual override.':
        '每日亏损限制是平台级停止规则，不允许手动覆盖。',
    'Maximum loss limit is an account survival rule; trading stops before breach.':
        '最大亏损限制是账户生存规则，触及前必须停止交易。',
    'Track daily loss, maximum loss, minimum trading days, and consistency requirements.':
        '跟踪每日亏损、最大亏损、最低交易日和一致性要求。',
    'Avoid new entries shortly before high-impact news unless the selected strategy explicitly allows it.':
        '除非所选策略明确允许，否则高影响新闻前避免新入场。',
    'Protect account first.': '优先保护账户。',
    'Avoid revenge trading.': '避免报复性交易。',
    'Avoid high-risk news if not part of the strategy.':
        '如果新闻交易不属于策略，则避免高风险新闻。',
    'Any all-in or gambling urge means the session is closed.':
        '任何孤注一掷或赌博冲动都代表本时段结束。',
    'After a win, keep the same risk and wait for the next valid setup.':
        '盈利后保持相同风险，等待下一个有效形态。',
    'After a loss, review whether rules were followed before trading again.':
        '亏损后先复盘是否遵守规则，再考虑继续交易。',
    'If a rule is broken, stop trading for the session and record the lesson.':
        '如果破坏规则，本交易时段停止，并记录教训。',
    'Review statistics, repeated mistakes, best setups, and one improvement focus.':
        '复盘统计数据、重复错误、最佳形态和一个改进重点。',
    'Overtrading rule: max trades per day is a hard session lock, not a target.':
        '过度交易规则：每日最多交易次数是硬性时段锁定，不是目标。',
    'Fear rule: if the checklist is complete and risk is reduced, follow the plan instead of hesitating.':
        '恐惧规则：如果检查清单完成且风险已降低，就按计划执行，不要犹豫。',
    'Early-exit rule: do not close profit early unless the written exit condition appears.':
        '过早离场规则：除非书面离场条件出现，否则不要提前止盈。',
    'Lot-size rule: loss recovery by increasing lot size is forbidden.':
        '手数规则：禁止通过加大手数来追回亏损。',
    'Plan-following rule: breaking one written rule ends the session.':
        '计划执行规则：破坏一条书面规则即结束本时段。',
    'Patience rule: no entry before the selected setup reaches its planned location.':
        '耐心规则：所选形态到达计划位置前不得入场。',
    'Signal-group rule: outside signals cannot override the selected strategy or risk rules.':
        '信号群规则：外部信号不能覆盖所选策略或风险规则。',
    'State rule: tired, stressed, or frustrated trading is blocked until the next session.':
        '状态规则：疲劳、压力或挫败状态下禁止交易，直到下一时段。',
    'Daily-loss rule: once the daily loss limit is reached, trading stops immediately.':
        '每日亏损规则：一旦达到每日亏损限制，立即停止交易。',
    'Maximum-loss rule: maximum loss protection overrides all trading opportunities.':
        '最大亏损规则：最大亏损保护优先于所有交易机会。',
    'Loser-holding rule: exit at the planned invalidation; no waiting for hope.':
        '持有亏损单规则：到达计划失效位就离场，不等待希望。',
    'Risk rule: every trade needs fixed risk, stop loss, and valid reward before entry.':
        '风险规则：每笔交易入场前都需要固定风险、止损和有效回报。',
    'Trade only the Asia session unless the plan is updated.':
        '除非更新计划，否则只交易亚洲盘。',
    'Trade only the London session.': '只交易伦敦盘。',
    'Trade only the New York session.': '只交易纽约盘。',
    'Trade only London/New York overlap or the selected London/New York sessions.':
        '只交易伦敦/纽约重叠时段，或已选择的伦敦/纽约时段。',
    'Trade only when the session is planned before market entry.':
        '只在入场前已计划好交易时段时交易。',
    'Prepare levels first and take only one planned decision.':
        '先准备关键位，并且只做一个计划内决策。',
    'Use a short watchlist and avoid constant monitoring.': '使用简短观察列表，避免持续盯盘。',
    'Use scheduled breaks to prevent overtrading.': '使用固定休息时间防止过度交易。',
    'Review market context, risk limits, and checklist before the session.':
        '交易时段前复盘市场背景、风险限制和检查清单。',
    'Before trading, review calendar, risk limits, and selected strategy.':
        '交易前复核日历、风险限制和所选策略。',
    'Impulsive traders must slow down and complete the checklist.':
        '冲动型交易者必须放慢速度并完成检查清单。',
    'Aggressive traders must treat risk limits as non-negotiable.':
        '激进型交易者必须把风险限制视为不可谈判。',
    'Emotional traders must pause when frustration, fear, or excitement is high.':
        '情绪型交易者在挫败、恐惧或兴奋过高时必须暂停。',
    'Overconfidence after wins can create oversized risk and unnecessary trades.':
        '盈利后的过度自信可能造成过大风险和不必要交易。',
    'Fearful traders should use smaller risk and clear invalidation.':
        '恐惧型交易者应使用更小风险和清晰失效位。',
    'Analytical traders should avoid delaying action after all plan conditions are met.':
        '分析型交易者在所有计划条件满足后，应避免拖延执行。',
    'Patience is useful, but hesitation should not replace written rules.':
        '耐心有用，但犹豫不应取代书面规则。',
    'Use one strategy playbook per trade and do not mix triggers after entry is selected.':
        '每笔交易只使用一个策略剧本；选定入场后不要混用触发条件。',
    'Invalid when price is choppy and indicators flip repeatedly.':
        '价格震荡且指标反复翻转时，形态无效。',
    'Invalid when there is not enough movement to reach the planned target.':
        '可用波动不足以到达计划目标时，形态无效。',
    'Invalid when spread, candle speed, or slippage prevents a clean stop-loss placement.':
        '点差、蜡烛速度或滑点导致无法清晰设置止损时，形态无效。',
    'Invalid within the restricted news window unless news trading is part of the tested strategy.':
        '在受限新闻窗口内无效，除非新闻交易属于已测试策略的一部分。',
    'Current market condition matches the chosen strategy playbook.':
        '当前市场状态符合所选策略剧本。',
    'Direction timeframe is aligned.': '方向时间周期已一致。',
    'Entry timeframe setup is present.': '入场时间周期形态已出现。',
    'Stop loss and take profit are defined before entry.': '止损和止盈已在入场前定义。',
    'Invalid setup conditions are not present.': '未出现无效形态条件。',
    'Track each market condition separately so trending, ranging, breakout, and reversal results are not mixed together.':
        '分别跟踪每种市场状态，避免把趋势、震荡、突破和反转结果混在一起。',
    'Support and resistance zones with rejection or retest confirmation':
        '支撑阻力区域结合拒绝反应或回踩确认',
    'Market structure, liquidity, order block, and FVG reaction':
        '市场结构、流动性、订单块和公允价值缺口反应',
    'MACD momentum with trend continuation confirmation': 'MACD 动能结合趋势延续确认',
    'RSI confirmation with structure context': 'RSI 确认结合结构背景',
    'EMA alignment with price-action pullback': '指数均线排列结合价格行为回调',
    'Trendline reaction, invalidation, and breakout retest': '趋势线反应、失效位和突破回踩',
    'Market structure continuation, BOS, CHOCH, and retest':
        '市场结构延续、BOS、CHOCH 和回踩',
    'Hybrid level, structure, and confirmation-based execution':
        '关键位、结构和确认结合的混合执行',
    'Use one clear timeframe only, but do not enter against obvious higher-timeframe structure.':
        '只使用一个清晰时间周期，但不要逆明显高周期结构入场。',
    'market execution': '市价执行',
    'limit order': '限价单',
    'stop order': '止损触发单',
    'pending order after retest': '回踩后的挂单',
    'planned execution': '计划内执行',
    'breakout retest': '突破回踩',
    'support/resistance rejection': '支撑/阻力拒绝反应',
    'pullback continuation': '回调延续',
    'order block reaction': '订单块反应',
    'FVG reaction': '公允价值缺口反应',
    'trendline rejection': '趋势线拒绝反应',
    'EMA pullback': '指数均线回调',
    'indicator crossover': '指标交叉',
    'reversal setup': '反转形态',
    'SNR rejection or breakout retest': '支撑阻力拒绝反应或突破回踩',
    'POI reaction after liquidity and structure confirmation':
        '流动性与结构确认后的 POI 反应',
    'trend pullback with indicator confirmation': '带指标确认的趋势回调',
    'trendline rejection or breakout retest': '趋势线拒绝反应或突破回踩',
    'structured technical setup': '结构化技术形态',
    'Price must react at a marked support or resistance zone.':
        '价格必须在已标记的支撑或阻力区域出现反应。',
    'Entry should use rejection candle or retest confirmation.':
        '入场应使用拒绝蜡烛或回踩确认。',
    'Higher-timeframe bias must be clear before selecting POI.':
        '选择 POI 前，高周期方向必须清晰。',
    'Require BOS/CHOCH, liquidity sweep, displacement, or POI reaction.':
        '需要 BOS/CHOCH、流动性扫荡、位移或 POI 反应。',
    'Trend direction must agree with the indicator signal.': '趋势方向必须与指标信号一致。',
    'Do not enter from the indicator alone without price structure.':
        '没有价格结构时，不要只凭指标入场。',
    'Trendline must have clear valid touches.': '趋势线必须有清晰有效触点。',
    'Entry requires reaction candle or breakout retest.': '入场需要反应蜡烛或突破回踩。',
    'Market structure must support the direction.': '市场结构必须支持交易方向。',
    'Entry must have a clear technical trigger.': '入场必须有清晰技术触发。',
    'Primary confirmation is candle rejection.': '主要确认是蜡烛拒绝反应。',
    'Primary confirmation is break of structure.': '主要确认是结构突破。',
    'Primary confirmation is CHOCH.': '主要确认是 CHOCH。',
    'Primary confirmation is retest.': '主要确认是回踩。',
    'Primary confirmation is volume expansion.': '主要确认是成交量扩张。',
    'Primary confirmation is EMA alignment.': '主要确认是指数均线排列。',
    'Primary confirmation is MACD crossover.': '主要确认是 MACD 交叉。',
    'Primary confirmation is RSI divergence.': '主要确认是 RSI 背离。',
    'Primary confirmation is trendline reaction.': '主要确认是趋势线反应。',
    'Use 1 strong confirmation only when the setup location is high quality.':
        '只有形态位置质量高时，才使用 1 个强确认。',
    'Use at least 2 confirmations before entry.': '入场前至少使用 2 个确认。',
    'Use 3 confirmations before entry.': '入场前使用 3 个确认。',
    'Use 4 or more confirmations and skip partial setups.':
        '使用 4 个或更多确认，并跳过只部分符合的形态。',
    'Invalid if price is in the middle of the range.': '价格位于区间中间时无效。',
    'Invalid if the support/resistance zone is not clearly marked.':
        '支撑/阻力区域未清晰标记时无效。',
    'Invalid if POI is forced without structure confirmation.':
        '没有结构确认却强行使用 POI 时无效。',
    'Invalid if there is no liquidity sweep, displacement, BOS, or CHOCH.':
        '没有流动性扫荡、位移、BOS 或 CHOCH 时无效。',
    'Invalid in choppy ranging conditions.': '震荡混乱的区间行情中无效。',
    'Invalid when indicator signal disagrees with market structure.':
        '指标信号与市场结构不一致时无效。',
    'Invalid if the trendline has weak or forced touches.': '趋势线触点弱或强行连接时无效。',
    'Invalid if price breaks the trendline without retest confirmation.':
        '价格突破趋势线但没有回踩确认时无效。',
    'Invalid when direction, setup location, and confirmation do not align.':
        '方向、形态位置和确认不一致时无效。',
    'Place SL below/above the invalidating structure.': '将止损放在失效结构下方/上方。',
    'Place SL outside the support/resistance zone.': '将止损放在支撑/阻力区域之外。',
    'Use fixed pips only if it still sits beyond technical invalidation.':
        '只有固定点数仍位于技术失效位之外时才使用。',
    'Use ATR-based SL with structure confirmation.': '使用基于 ATR 且有结构确认的止损。',
    'Place SL beyond the previous candle high/low if it matches invalidation.':
        '若上一根蜡烛高/低点符合失效位，则把止损放在其外侧。',
    'Place SL beyond technical invalidation.': '将止损放在技术失效位之外。',
    'Place SL outside the SNR zone.': '将止损放在支撑阻力区域之外。',
    'Place SL beyond the invalidation high/low of the POI.':
        '将止损放在 POI 失效高/低点之外。',
    'Place SL beyond structure or use ATR-based invalidation.':
        '将止损放在结构之外，或使用基于 ATR 的失效位。',
    'Place SL beyond trendline invalidation.': '将止损放在趋势线失效位之外。',
    'Place SL beyond the technical invalidation point.': '将止损放在技术失效点之外。',
    'Take profit at fixed risk-reward, preferably minimum 1:2.':
        '按固定风险回报止盈，最好至少 1:2。',
    'Take profit at previous high/low.': '在前高/前低止盈。',
    'Take profit at the next support/resistance level.': '在下一个支撑/阻力位止盈。',
    'Partial close only at planned levels.': '只在计划位进行部分平仓。',
    'Use trailing stop only after price confirms continuation.':
        '只有价格确认延续后才使用移动止损。',
    'Exit when indicator momentum fails and structure agrees.':
        '当指标动能失效且结构确认时离场。',
    'Take profit at planned technical target.': '在计划技术目标位止盈。',
    'Take profit at next key level or minimum planned RR.':
        '在下一个关键位或最低计划风险回报处止盈。',
    'Take profit at liquidity target or structure target.': '在流动性目标或结构目标止盈。',
    'Take profit at fixed RR or next structure.': '在固定风险回报或下一个结构位止盈。',
    'Take profit at next structure level.': '在下一个结构位止盈。',
    'Take profit at planned structure, liquidity, or RR target.':
        '在计划结构位、流动性位或风险回报目标止盈。',
    'Partial close is allowed only when planned before entry; protect the remaining position.':
        '只有入场前已计划时才允许部分平仓；同时保护剩余仓位。',
    'Trail only after price reaches the planned management area.':
        '只有价格到达计划管理区域后才移动止损。',
    'Do not move SL/TP emotionally; manage only by the technical plan.':
        '不要因情绪移动止损/止盈；只按技术计划管理。',
    'Suitable for traders who can wait for price to reach key levels.':
        '适合能等待价格到达关键位的交易者。',
    'Suitable for traders who can read structure, liquidity, and POI context.':
        '适合能解读结构、流动性和 POI 背景的交易者。',
    'Suitable for traders who prefer rule-based trend confirmation.':
        '适合偏好规则化趋势确认的交易者。',
    'Suitable for traders who can validate trendline quality objectively.':
        '适合能客观验证趋势线质量的交易者。',
    'Suitable for traders who want a structured technical method.':
        '适合想使用结构化技术方法的交易者。',
    'Low Volatility Rule: avoid trades when the available range cannot reach the planned target.':
        '低波动规则：可用区间无法到达计划目标时避免交易。',
    'News-Driven Market Rule: no entry inside the restricted news window unless this exact setup has been tested.':
        '新闻驱动市场规则：除非该形态已被测试，否则受限新闻窗口内不入场。',
    'Single Market Strategy: take only the setup type selected in this questionnaire and keep the rule set unchanged.':
        '单一市场策略：只交易本问卷选择的形态类型，并保持规则集不变。',
    'Use the strategy only when the market condition is clear before entry.':
        '只在入场前市场状态清晰时使用该策略。',
    'Before each trade, choose the active market condition first; the condition decides which setup is allowed.':
        '每笔交易前先选择当前有效市场状态；市场状态决定允许哪种形态。',
    'Trending condition: direction timeframe must show higher highs/higher lows or lower highs/lower lows.':
        '趋势条件：方向时间周期必须显示更高高点/更高低点，或更低高点/更低低点。',
    'Ranging condition: only trade reactions at the range boundary; no entries in the middle.':
        '震荡条件：只交易区间边界反应，不在中间入场。',
    'Breakout condition: require breakout, acceptance, and retest before entry.':
        '突破条件：入场前需要突破、接受和回踩。',
    'Reversal condition: require exhaustion plus structure shift before entry.':
        '反转条件：入场前需要衰竭加结构转换。',
    'High volatility condition: skip if spread, slippage, or candle speed makes risk unclear.':
        '高波动条件：若点差、滑点或蜡烛速度导致风险不清晰，则跳过。',
    'Low volatility condition: skip if the target is too close or momentum is absent.':
        '低波动条件：目标太近或缺少动能时跳过。',
    'News condition: check the economic calendar and avoid unplanned news entries.':
        '新闻条件：检查经济日历，避免计划外新闻入场。',
    'When more than one strategy qualifies, choose the cleanest setup only; do not stack extra trades.':
        '当多个策略同时符合时，只选择最清晰的形态；不要叠加额外交易。',
    'Use reduced risk in high-impact or fast-moving conditions.':
        '在高影响或快速波动环境中使用降低后的风险。',
