    'No trading plan found. You can still save this journal.':
        '未找到交易计划，你仍然可以保存此交易日志。',
    'Select Trading Plan': '选择交易计划',
    'Trading plan is optional for this journal.': '此交易日志可不选择交易计划。',
    'How to Define Your Trading Plan': '如何制定你的交易计划',
    'Start simple, follow your rules, and improve the plan through your journal.':
        '从简单规则开始，坚持执行，并通过交易日志不断优化计划。',
    'What is a trading plan?': '什么是交易计划？',
    'A trading plan is a written set of rules that guides when you enter, manage, and exit a trade. It helps you avoid random decisions and keeps your trading consistent.':
        '交易计划是一套写下来的规则，用来指导你什么时候进场、如何管理仓位，以及什么时候离场。它可以帮助你避免随机下单，让交易更有一致性。',
    'Why do you need a trading plan?': '为什么你需要交易计划？',
    'Without a trading plan, traders often rely on emotion, fear, greed, or FOMO. A trading plan helps you trade based on rules instead of mood.':
        '如果没有交易计划，交易员很容易被情绪、恐惧、贪婪或 FOMO 影响。交易计划可以帮助你根据规则交易，而不是根据当下情绪做决定。',
    'What should your trading plan include?': '你的交易计划应该包含什么？',
    'Market/session you trade': '交易市场/交易时段',
    'Entry conditions': '入场条件',
    'Stop loss rules': '止损规则',
    'Take profit rules': '止盈规则',
    'Maximum daily loss': '每日最大亏损',
    'Confirmation rules': '确认信号规则',
    'No-trade conditions': '不交易的条件',
    'Post-trade review notes': '交易后复盘记录',
    'Example trading plan': '交易计划示例',
    'Example: I only trade XAUUSD during London or New York session. I only enter when price reaches my key level, confirms market structure, and gives a valid rejection or breakout retest. I risk maximum 1% per trade and stop trading after 2 losses in one day.':
        '例子：我只在伦敦盘或纽约盘交易 XAUUSD。只有当价格到达我的关键价位，并且市场结构确认，同时出现有效的拒绝反应或突破回踩时，我才会进场。每笔交易最多风险 1%，一天亏损 2 次后停止交易。',
    'Reminder': '提醒',
    'Your trading plan does not need to be perfect at the beginning. Start simple, follow it consistently, and improve it through your trading journal.':
        '你的交易计划一开始不需要完美。先从简单规则开始，坚持执行，并通过交易日志不断优化。',
