    'You are building consistency and need simple rules before increasing risk.':
        '你正在建立一致性，在提高风险前需要简单清晰的规则。',
    'You have enough experience to use a structured plan with measurable limits.':
        '你已有足够经验，可以使用带有可衡量限制的结构化计划。',
    'Your answers show a need for strict emotional-control rules before entries.':
        '你的答案显示，入场前需要严格的情绪控制规则。',
    'Your available screen time favors fewer planned decisions instead of constant monitoring.':
        '你的可用看盘时间更适合较少但有计划的决策，而不是持续盯盘。',
    'Your plan should protect account survival before growth.':
        '你的计划应先保护账户生存，再考虑增长。',
    'Use a simple SNR + Market Structure plan with clear confirmation rules.':
        '使用简单的支撑阻力 + 市场结构计划，并设置清晰确认规则。',
    'Use higher-timeframe bias before lower-timeframe entry confirmation.':
        '先确认高周期方向，再用低周期确认入场。',
    'Mark major support and resistance first, then wait for rejection or retest.':
        '先标记主要支撑与阻力，再等待拒绝反应或回踩。',
    'Confirm current market structure before choosing continuation or reversal.':
        '先确认当前市场结构，再选择延续或反转交易。',
    'Use order block or FVG only after market structure gives context.':
        '只有在市场结构提供背景后，才使用订单块或 FVG。',
    'Use trendlines as context and wait for reaction or break-and-retest confirmation.':
        '把趋势线作为背景，并等待反应或突破回踩确认。',
    'Use EMA, MACD, or RSI as confirmation, not as the only reason to enter.':
        '把 EMA、MACD 或 RSI 当作确认，而不是唯一入场理由。',
    'Combine level, structure, candle confirmation, and risk before entry.':
        '入场前结合关键位、结构、K 线确认和风险。',
    'Inside ranges, trade only clean edges and avoid entries in the middle.':
        '在震荡区间中，只交易清晰边缘，避免在中间位置入场。',
    'For breakout conditions, wait for close and retest instead of chasing the first candle.':
        '遇到突破行情时，等待收线与回踩，不要追第一根突破蜡烛。',
    'For reversal trades, require structure shift before entering against the prior trend.':
        '做反转交易时，必须先出现结构转换，再逆原趋势入场。',
    'Require multiple confirmations before entry and skip trades that are only partly aligned.':
        '入场前要求多个确认，跳过只部分符合条件的交易。',
    'Do not rely on one signal alone when emotion or market speed is high.':
        '当情绪或市场速度较高时，不要只依赖单一信号。',
    'Primary entry model is breakout retest.': '主要入场模型是突破回踩。',
    'Primary entry model is rejection from support or resistance.':
        '主要入场模型是支撑或阻力拒绝反应。',
    'Primary entry model is pullback continuation.': '主要入场模型是回调延续。',
    'Primary entry model is order block or FVG mitigation.':
        '主要入场模型是订单块或 FVG 回补。',
    'Primary entry model is trend continuation.': '主要入场模型是趋势延续。',
    'Primary entry model is reversal after structure shift.':
        '主要入场模型是结构转换后的反转。',
    'Use only one clear entry model at a time until results are reviewed.':
        '在结果完成复盘前，每次只使用一个清晰的入场模型。',
    'Only enter when market bias, setup location, confirmation, and risk are aligned.':
        '只有当市场方向、形态位置、确认信号和风险都一致时才入场。',
    'Wait for a pullback or retest; do not enter after a strong move without confirmation.':
        '等待回调或回踩；强势移动后没有确认不要入场。',
    'For scalping, trade only during active volume and when spread is acceptable.':
        '剥头皮只在成交活跃且点差可接受时交易。',
    'For swing trades, confirm the setup on H4 or Daily before using H1 for execution.':
        '波段交易先在 H4 或日线确认形态，再使用 H1 执行。',
    'The pre-trade checklist is mandatory before every entry.':
        '每次入场前必须完成交易前检查清单。',
    'Define the invalidation, target, and management rule before entry.':
        '入场前先定义失效位、目标位和持仓管理规则。',
    'Do not close early unless the original setup is invalidated or the plan allows partial profit.':
        '除非原始形态失效，或计划允许部分止盈，否则不要提前平仓。',
    'Avoid over-managing swing trades after the planned stop and target are set.':
        '计划止损和目标设置后，避免过度管理波段交易。',
    'For early exits, write the reason before closing and compare it with the original plan.':
        '若想提前离场，先写下原因，并与原计划对比。',
    'Place stop loss beyond the technical invalidation point, not at a random money amount.':
        '止损应放在技术失效位之外，而不是随机的金额位置。',
    'For swing trades, use wider structure-based stops and reduce lot size accordingly.':
        '波段交易使用较宽的结构止损，并相应降低手数。',
    'For scalping, stop loss must be tight but still outside the setup invalidation.':
        '剥头皮止损要紧凑，但仍必须放在形态失效位之外。',
    'Take profit at planned liquidity, support, resistance, or measured-move areas.':
        '在预先计划的流动性、支撑、阻力或测量目标区域止盈。',
    'Partial profit is allowed only when it was planned before entry.':
        '只有入场前已计划时，才允许部分止盈。',
    'Do not accept trades that cannot reasonably reach at least 1:2.':
        '无法合理达到至少 1:2 的交易不应接受。',
    'Risk is fixed before entry and must not be increased to recover a loss.':
        '风险必须在入场前固定，不能为了追回亏损而增加。',
    'Keep risk conservative until at least 20 planned trades are reviewed.':
        '在至少复盘 20 笔计划内交易前，保持保守风险。',
    'Use prop firm daily drawdown and maximum loss limits as hard stop rules.':
        '把 Prop Firm 每日回撤和最大亏损限制作为硬性停止规则。',
    'The max trades per day is a hard limit, not a target.':
        '每日最多交易次数是硬性上限，不是目标。',
    'Stop trading for the day after two consecutive losses.': '连续亏损两笔后，当天停止交易。',
    'Every setup must meet the minimum risk-reward ratio before entry.':
        '每个形态入场前都必须符合最低风险回报比。',
    'Missing a trade is not a signal to chase; wait for the next planned setup.':
        '错过交易不是追单信号；等待下一个计划内机会。',
    'After a loss, take a cooldown before looking for another setup.':
        '亏损后先冷静，再寻找下一个机会。',
    'Confidence must be checked against written rules before increasing activity.':
        '增加交易频率前，必须用书面规则检查自己的信心是否过度。',
    'If fear is high, reduce position size or wait for a cleaner setup.':
        '如果恐惧感较高，降低仓位或等待更清晰的形态。',
    'Take profit must follow the plan, not the feeling that more is available.':
        '止盈必须遵守计划，而不是凭感觉认为还能赚更多。',
    'Impulsive traders must slow the entry process and require checklist confirmation.':
        '冲动型交易者必须放慢入场流程，并要求检查清单确认。',
    'Aggressive traders must treat risk limits as non-negotiable.':
        '进取型交易者必须把风险限制视为不可谈判。',
    'Emotional traders must pause when frustration, fear, or excitement is high.':
        '情绪化交易者在挫败、恐惧或兴奋过高时必须暂停。',
    'Overconfidence after wins can create oversized risk and unnecessary trades.':
        '盈利后的过度自信可能造成过大风险和不必要交易。',
    'Fearful traders should focus on smaller risk and clear invalidation.':
        '恐惧型交易者应专注较小风险和清晰失效条件。',
    'Analytical traders should avoid delaying entries after all planned conditions are met.':
        '分析型交易者在所有计划条件满足后，应避免过度拖延入场。',
    'No trade when market direction is unclear.': '市场方向不清晰时不交易。',
    'No trade when risk cannot be calculated before entry.': '入场前无法计算风险时不交易。',
